answer:
function findKeys(code) {
  const result = [];
  code.split("\n").forEach((line, i) => {
    if (/\w*(KEY|SECRET|PASSWORD)\w*\s*=\s*["']/.test(line)) result.push(i + 1);
  });
  return result;
}

console.log(findKeys('const API_KEY = "abcd";\nconst DB_PASSWORD = process.env.DB_PASSWORD;'));

