function loadConfig(env) {
  if (!env.API_KEY) throw new Error("API_KEY が設定されていません");
  return { apiKey: env.API_KEY, debug: env.DEBUG === "true" };
}

console.log(loadConfig({ API_KEY: "k1" }));
